// Calendar Convert sub-menu
case "mailContext-calendar-convert-event-menuitem":
  top.calendarExtract.extractFromEmail(
    gDBView.hdrForFirstSelectedMessage,
    true
  );
  break;
case "mailContext-calendar-convert-task-menuitem":
  top.calendarExtract.extractFromEmail(
    gDBView.hdrForFirstSelectedMessage,
    false
  );
  break;
